// Triaje de Red Cuidar Formosa: clasifica la consulta del vecino por signos y síntomas de dengue
// (criterios del Ministerio de Salud) y devuelve { respuesta, nivelTriaje } a la API.
// No usa el modelo: son reglas fijas, siempre dan el mismo resultado y no fallan.
const cuerpo = $('Webhook').first().json.body ?? {};
const mensaje = String(cuerpo.mensaje ?? cuerpo.pregunta ?? cuerpo.chatInput ?? '');
let respuesta = String($input.first().json.output ?? '').trim();

// Minúsculas y sin tildes; "no tengo fiebre" no cuenta como fiebre.
const texto = mensaje.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const negada = (i) => /\b(no|sin|nunca|ni)\b[^.,;!?]{0,18}$/.test(texto.slice(Math.max(0, i - 25), i));
const aparece = (patron) => [...texto.matchAll(new RegExp(patron.source, 'g'))].some((m) => !negada(m.index));

// Signos de alarma: guardia o 107 ya.
const ALARMA = [
  /dolor (muy )?(fuerte |intenso )?(de |en la |en el )?(panza|abdom\w*|estomago|barriga)/,
  /(panza|abdomen|estomago|barriga) (me )?duele (mucho|fuerte)/,
  /vomit\w* (mucho|seguido|todo|sin parar|a cada rato|varias veces)|no (para|paro|deja|dejo) de vomitar|vomit\w* (y |que )?no para/,
  /sangr\w*|hemorragia|encias|moretones/,
  /desmay\w*|perdi\w* el conocimiento|convuls\w*/,
  /(cuesta|dificultad para|falta el|falta de|no (puedo|puede) ) ?(respirar|aire)|ahog\w*/,
  /somnolien\w*|muy dormid\w*|no (se )?(despierta|reacciona)|muy irritable|confundid\w*/,
  /(manos|pies|piel) (frias|helad\w*)|labios morados/,
];
// Síntomas compatibles con dengue: consultar hoy.
const SINTOMAS = [
  /fiebre|temperatura|calentura|3[89](,|\.)?\d? ?(grados)?/,
  /dolor de cabeza|me duele la cabeza|cefalea/,
  /detras de los ojos|dolor (de|en los) ojos|me duelen los ojos/,
  /dolor (muscular|de huesos|articular|de cuerpo|en el cuerpo|en las articulaciones)|me duele (todo )?el cuerpo|me duelen los huesos/,
  /sarpullido|manchas (rojas|en la piel)|erupcion|brote/,
  /nauseas|vomit\w*|diarrea/,
];
const LEVES = [/picad\w*|me pica|ronchas?|cansad\w*|malestar|me siento mal|decaid\w*/];

let nivelTriaje = 'SIN_RIESGO';
if (ALARMA.some(aparece)) nivelTriaje = 'URGENTE';
else if (SINTOMAS.some(aparece)) nivelTriaje = 'MODERADO';
else if (LEVES.some(aparece)) nivelTriaje = 'LEVE';

// Si el modelo no respondió, se devuelve vacío: la API contesta con su asistente básico.
if (respuesta) {
  if (nivelTriaje === 'URGENTE' && !respuesta.includes('107')) {
    respuesta += '\n\nLo que contás puede ser un signo de alarma: andá ya a la guardia más cercana o llamá al 107.';
  }
  if (nivelTriaje === 'MODERADO' && !/centro de salud|guardia|m[eé]dic/i.test(respuesta)) {
    respuesta += '\n\nConsultá hoy en tu centro de salud y no te automediques: nada de aspirina ni ibuprofeno.';
  }
  if (nivelTriaje !== 'SIN_RIESGO') respuesta += '\n\nEsta orientación no reemplaza la consulta médica.';
}

return [{ json: { respuesta, nivelTriaje } }];
